CREATE TABLE "org_units" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "parent_id" bigint,
  "level" org_level NOT NULL,
  "code" varchar(50) UNIQUE NOT NULL,
  "name" varchar(200) NOT NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "sync_run_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_org_units_not_own_parent" CHECK (parent_id is null or parent_id <> id),
  CONSTRAINT "chk_org_units_group_root" CHECK ((level = 'group') = (parent_id is null))
);

CREATE TABLE "employees" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_code" varchar(50) UNIQUE,
  "full_name" varchar(200) NOT NULL,
  "email" varchar(320) UNIQUE NOT NULL,
  "org_unit_id" bigint,
  "project_ids" bigint[],
  "left_on" date,
  "source" data_source NOT NULL DEFAULT 'api',
  "sync_run_id" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_employees_email_lowercase" CHECK (email = lower(email)),
  CONSTRAINT "chk_employees_ilvg_only" CHECK (source = 'api'),
  CONSTRAINT "chk_employees_sync_provenance" CHECK (sync_run_id is not null)
);

CREATE TABLE "roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(100) NOT NULL,
  "description" text
);

CREATE TABLE "permissions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "feature_code" varchar(60) NOT NULL,
  "action" permission_action NOT NULL,
  "description" text
);

CREATE TABLE "role_permissions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_id" bigint NOT NULL,
  "permission_id" bigint NOT NULL
);

CREATE TABLE "user_accounts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" bigint UNIQUE NOT NULL,
  "role_id" bigint NOT NULL,
  "password_hash" varchar(255),
  "password_token_hash" char(64) UNIQUE,
  "password_token_expires_at" timestamptz,
  "failed_login_count" int NOT NULL DEFAULT 0,
  "locked_until" timestamptz,
  "last_login_at" timestamptz,
  "disabled_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_user_accounts_failed_count" CHECK (failed_login_count >= 0),
  CONSTRAINT "chk_user_accounts_password_token" CHECK ((password_token_hash is null) = (password_token_expires_at is null))
);

CREATE TABLE "user_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_account_id" bigint NOT NULL,
  "token_hash" char(64) UNIQUE NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "expires_at" timestamptz NOT NULL,
  CONSTRAINT "chk_user_sessions_expiry" CHECK (expires_at > created_at)
);

CREATE TABLE "user_org_units" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_account_id" bigint NOT NULL,
  "org_unit_id" bigint NOT NULL
);

CREATE TABLE "vendors" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(50) UNIQUE NOT NULL,
  "name" varchar(200) UNIQUE NOT NULL,
  "kind" vendor_kind NOT NULL DEFAULT 'publisher',
  "website" varchar(500),
  "support_contact" varchar(500),
  "is_active" boolean NOT NULL DEFAULT true,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "software_categories" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "software_products" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "vendor_id" bigint NOT NULL,
  "category_id" bigint,
  "name" varchar(200) NOT NULL,
  "description" text,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "license_plans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "connector_id" bigint NOT NULL,
  "external_name" varchar(200) NOT NULL,
  "external_ref" varchar(200),
  "sap_name" varchar(200),
  "product_id" bigint,
  "archetype" license_archetype NOT NULL DEFAULT 'allocation',
  "unit" varchar(30) NOT NULL DEFAULT 'seat',
  "owner_org_unit_id" bigint NOT NULL,
  "last_sync_run_id" bigint,
  "usage_granularity" usage_granularity,
  "has_daily_activity" boolean,
  "monitoring_since" date,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_license_plans_daily_activity" CHECK (has_daily_activity is null or usage_granularity = 'per_subject'),
  CONSTRAINT "chk_license_plans_monitoring_since" CHECK (usage_granularity is null or monitoring_since is not null)
);

CREATE TABLE "entitlement_lines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "quantity" numeric(20,4),
  "valid_from" date NOT NULL,
  "valid_to" date,
  "commercial_term" commercial_term NOT NULL,
  "external_ref" varchar(200),
  "pr_number" varchar(50),
  "import_batch_id" bigint,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_entitlement_lines_quantity" CHECK (quantity is null or quantity >= 0),
  CONSTRAINT "chk_entitlement_lines_payg_no_quota" CHECK (commercial_term <> 'pay_as_you_go' or quantity is null),
  CONSTRAINT "chk_entitlement_lines_validity" CHECK (valid_to is null or valid_to >= valid_from),
  CONSTRAINT "chk_entitlement_lines_provenance" CHECK ((import_batch_id is null) = (created_by is not null)),
  CONSTRAINT "chk_entitlement_lines_po_ref" CHECK ((import_batch_id is not null) = (external_ref is not null)),
  CONSTRAINT "chk_entitlement_lines_manual_no_pr" CHECK (import_batch_id is not null or pr_number is null)
);

CREATE TABLE "connectors" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" connector_kind NOT NULL DEFAULT 'usage',
  "org_unit_id" bigint,
  "vendor_id" bigint,
  "name" varchar(200) UNIQUE NOT NULL,
  "connector_type" varchar(60) NOT NULL,
  "api_url" varchar(500) NOT NULL,
  "auth_type" connector_auth NOT NULL,
  "credentials_ref" text NOT NULL,
  "contact_name" varchar(100),
  "contact_email" varchar(160),
  "sync_interval_hours" int NOT NULL DEFAULT 6,
  "reconfigured_at" timestamptz NOT NULL DEFAULT (now()),
  "paused_at" timestamptz,
  "paused_by" bigint,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_connectors_usage_target" CHECK ((kind = 'usage') = (org_unit_id is not null and vendor_id is not null)),
  CONSTRAINT "chk_connectors_usage_contact" CHECK (kind <> 'usage' or (contact_name is not null and contact_email is not null)),
  CONSTRAINT "chk_connectors_interval" CHECK (sync_interval_hours > 0),
  CONSTRAINT "chk_connectors_paused" CHECK ((paused_at is null) = (paused_by is null)),
  CONSTRAINT "chk_connectors_https" CHECK (api_url like 'https://%')
);

CREATE TABLE "sync_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "connector_id" bigint NOT NULL,
  "trigger" sync_trigger NOT NULL DEFAULT 'scheduled',
  "status" run_status NOT NULL DEFAULT 'running',
  "data_date" date NOT NULL,
  "window_start" timestamptz,
  "window_end" timestamptz,
  "error_message" text,
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz,
  CONSTRAINT "chk_sync_runs_finished" CHECK ((status = 'running') = (finished_at is null)),
  CONSTRAINT "chk_sync_runs_duration" CHECK (finished_at is null or finished_at >= started_at),
  CONSTRAINT "chk_sync_runs_window" CHECK (window_end is null or window_start is null or window_end >= window_start),
  CONSTRAINT "chk_sync_runs_error" CHECK ((status = 'failed') = (error_message is not null)),
  CONSTRAINT "chk_sync_runs_paused" CHECK (status <> 'paused' or finished_at = started_at)
);

CREATE TABLE "raw_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "sync_run_id" bigint NOT NULL,
  "record_type" varchar(60) NOT NULL,
  "external_id" varchar(200),
  "payload" jsonb NOT NULL,
  "fetched_at" timestamptz NOT NULL DEFAULT (now()),
  "normalized_at" timestamptz,
  "normalize_error" varchar(200),
  CONSTRAINT "chk_raw_records_normalize_error" CHECK (normalize_error is null or normalized_at is not null)
);

CREATE TABLE "files" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "storage_key" varchar(500) UNIQUE NOT NULL,
  "original_name" varchar(255) NOT NULL,
  "content_type" varchar(100) NOT NULL,
  "size_bytes" bigint NOT NULL,
  "checksum" char(64) NOT NULL,
  "uploaded_by" bigint,
  "uploaded_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_files_size" CHECK (size_bytes > 0 and size_bytes <= 10485760)
);

CREATE TABLE "import_batches" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "import_type" import_kind NOT NULL,
  "file_id" bigint NOT NULL,
  "target_org_unit_id" bigint,
  "period_from" date,
  "period_to" date,
  "preview_key" uuid UNIQUE NOT NULL,
  "based_on_import_id" bigint,
  "version_no" int,
  "note" text,
  "status" import_status NOT NULL DEFAULT 'previewed',
  "rows_total" int NOT NULL DEFAULT 0,
  "rows_added" int NOT NULL DEFAULT 0,
  "rows_updated" int NOT NULL DEFAULT 0,
  "rows_removed" int NOT NULL DEFAULT 0,
  "rows_rejected" int NOT NULL DEFAULT 0,
  "error_report" jsonb,
  "imported_by" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "confirmed_at" timestamptz,
  CONSTRAINT "chk_import_batches_confirmed" CHECK ((status = 'confirmed') = (confirmed_at is not null)),
  CONSTRAINT "chk_import_batches_budget_target" CHECK ((import_type = 'budget') = (target_org_unit_id is not null and period_from is not null and period_to is not null)),
  CONSTRAINT "chk_import_batches_period" CHECK (period_to is null or period_to >= period_from),
  CONSTRAINT "chk_import_batches_budget_version" CHECK ((version_no is not null) = (import_type = 'budget' and status = 'confirmed')),
  CONSTRAINT "chk_import_batches_version_positive" CHECK (version_no is null or version_no > 0),
  CONSTRAINT "chk_import_batches_budget_only" CHECK (import_type = 'budget' or (based_on_import_id is null and note is null)),
  CONSTRAINT "chk_import_batches_months_of_one_year" CHECK (period_from is null or (extract(day from period_from) = 1 and extract(day from period_to) = 1 and extract(year from period_from) = extract(year from period_to))),
  CONSTRAINT "chk_import_batches_counts" CHECK (rows_total >= 0 and rows_added >= 0 and rows_updated >= 0 and rows_removed >= 0 and rows_rejected >= 0)
);

CREATE TABLE "subjects" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "connector_id" bigint NOT NULL,
  "holder_type" holder_type NOT NULL DEFAULT 'person',
  "identifier" varchar(320) NOT NULL,
  "employee_id" bigint,
  "org_unit_id" bigint,
  "sync_run_id" bigint NOT NULL,
  CONSTRAINT "chk_subjects_person_employee" CHECK ((holder_type = 'person') = (employee_id is not null)),
  CONSTRAINT "chk_subjects_person_no_unit" CHECK (holder_type <> 'person' or org_unit_id is null),
  CONSTRAINT "chk_subjects_identifier_lowercase" CHECK (identifier = lower(identifier))
);

CREATE TABLE "license_assignments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "subject_id" bigint NOT NULL,
  "assigned_on" date,
  "ended_on" date,
  "last_active_at" timestamptz,
  "sync_run_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_license_assignments_dates" CHECK (ended_on is null or assigned_on is null or ended_on >= assigned_on)
);

CREATE TABLE "usage_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "license_plan_id" bigint NOT NULL,
  "subject_id" bigint,
  "metric" usage_metric NOT NULL,
  "period_start" date NOT NULL,
  "period_end" date NOT NULL,
  "quantity" numeric(20,4) NOT NULL,
  "sync_run_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_usage_records_period" CHECK (period_end >= period_start),
  CONSTRAINT "chk_usage_records_quantity" CHECK (quantity >= 0),
  CONSTRAINT "chk_usage_records_active_subjects_aggregate" CHECK (metric <> 'active_subjects' or subject_id is null),
  CONSTRAINT "chk_usage_records_active_days" CHECK (metric <> 'active_days' or (subject_id is not null and quantity <= period_end - period_start + 1)),
  CONSTRAINT "chk_usage_records_whole_counts" CHECK (metric not in ('active_subjects', 'active_days', 'peak_concurrent') or quantity = trunc(quantity))
);

CREATE TABLE "plan_daily_snapshots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "snapshot_date" date NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "purchased_qty" numeric(20,4),
  "is_unlimited" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_plan_daily_snapshots_unlimited" CHECK (not is_unlimited or purchased_qty is null)
);

CREATE TABLE "plan_unit_daily_snapshots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "snapshot_date" date NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint,
  "active_qty" numeric(20,4) NOT NULL,
  "inactive_qty" numeric(20,4) NOT NULL,
  "no_activity_qty" numeric(20,4) NOT NULL,
  "not_monitored_qty" numeric(20,4) NOT NULL,
  "shared_service_qty" numeric(20,4) NOT NULL,
  "used_qty" numeric(20,4),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_plan_unit_daily_snapshots_counts" CHECK (active_qty >= 0 and inactive_qty >= 0 and no_activity_qty >= 0 and not_monitored_qty >= 0),
  CONSTRAINT "chk_plan_unit_daily_snapshots_shared" CHECK (shared_service_qty between 0 and active_qty + inactive_qty + no_activity_qty + not_monitored_qty)
);

CREATE TABLE "employee_app_usage" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" bigint NOT NULL,
  "application_name" varchar(200) NOT NULL,
  "usage_date" date NOT NULL,
  "active_minutes" int,
  "product_id" bigint,
  "sync_run_id" bigint NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_employee_app_usage_minutes" CHECK (active_minutes is null or active_minutes >= 0)
);

CREATE TABLE "budget_plan_lines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "import_batch_id" bigint NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "license_name" varchar(200) NOT NULL,
  "license_plan_id" bigint,
  "month" date NOT NULL,
  "planned_quantity" numeric(20,4) NOT NULL,
  "planned_amount" numeric(18,2) NOT NULL,
  "currency" char(3) NOT NULL,
  "superseded_by_import_id" bigint,
  CONSTRAINT "chk_budget_plan_lines_quantity" CHECK (planned_quantity >= 0),
  CONSTRAINT "chk_budget_plan_lines_amount" CHECK (planned_amount >= 0),
  CONSTRAINT "chk_budget_plan_lines_month_start" CHECK (extract(day from month) = 1),
  CONSTRAINT "chk_budget_plan_lines_superseded" CHECK (superseded_by_import_id is null or superseded_by_import_id <> import_batch_id)
);

CREATE TABLE "cost_allocations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "accounting_period_id" bigint NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "bucket" cost_bucket NOT NULL,
  "org_unit_id" bigint NOT NULL,
  "method" allocation_method NOT NULL,
  "basis_qty" numeric(20,4),
  "filled_days" int,
  "used_amount" numeric(18,2),
  "wasted_amount" numeric(18,2),
  "not_evaluated_amount" numeric(18,2),
  "computed_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_cost_allocations_basis" CHECK (basis_qty is null or basis_qty >= 0),
  CONSTRAINT "chk_cost_allocations_filled_days" CHECK (((method = 'per_seat') = (filled_days is not null)) and (filled_days is null or filled_days between 0 and 31)),
  CONSTRAINT "chk_cost_allocations_unknown" CHECK ((used_amount is null) = (wasted_amount is null) and (wasted_amount is null) = (not_evaluated_amount is null)),
  CONSTRAINT "chk_cost_allocations_unallocated_unused" CHECK (bucket <> 'unallocated' or used_amount is null or used_amount = 0)
);

CREATE TABLE "expenses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "expense_date" date NOT NULL,
  "service_from" date,
  "service_to" date,
  "amount" numeric(18,2) NOT NULL,
  "currency" char(3) NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "entitlement_line_id" bigint,
  "org_unit_id" bigint NOT NULL,
  "description" text,
  "invoice_file_id" bigint,
  "accrual_schedule" jsonb,
  "external_ref" varchar(200),
  "import_batch_id" bigint,
  "created_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_expenses_amount_not_zero" CHECK (amount <> 0),
  CONSTRAINT "chk_expenses_service_pair" CHECK ((service_from is null) = (service_to is null)),
  CONSTRAINT "chk_expenses_service_term" CHECK (service_to is null or service_to >= service_from),
  CONSTRAINT "chk_expenses_provenance" CHECK ((import_batch_id is null) = (created_by is not null)),
  CONSTRAINT "chk_expenses_invoice_ref" CHECK ((import_batch_id is not null) = (external_ref is not null)),
  CONSTRAINT "chk_expenses_po_line" CHECK (import_batch_id is null or entitlement_line_id is not null)
);

CREATE TABLE "accounting_periods" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "org_unit_id" bigint NOT NULL,
  "month" date NOT NULL,
  "closed_at" timestamptz,
  "closed_by" bigint,
  CONSTRAINT "chk_accounting_periods_month_start" CHECK (extract(day from month) = 1)
);

CREATE TABLE "exchange_rates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "from_currency" char(3) NOT NULL,
  "rate" numeric(18,8) NOT NULL,
  "effective_from" date NOT NULL,
  "declared_by" bigint,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_exchange_rates_rate" CHECK (rate > 0)
);

CREATE TABLE "detection_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data_date" date NOT NULL,
  "rule_version" varchar(20) NOT NULL,
  "status" run_status NOT NULL DEFAULT 'running',
  "started_at" timestamptz NOT NULL DEFAULT (now()),
  "finished_at" timestamptz,
  CONSTRAINT "chk_detection_runs_finished" CHECK ((status = 'running') = (finished_at is null)),
  CONSTRAINT "chk_detection_runs_status" CHECK (status <> 'paused')
);

CREATE TABLE "detection_results" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "detection_run_id" bigint NOT NULL,
  "license_plan_id" bigint NOT NULL,
  "org_unit_id" bigint,
  "check_type" detection_check NOT NULL,
  "flagged_qty" numeric(20,4),
  "monthly_cost" numeric(18,2),
  "flagged_since" date,
  CONSTRAINT "chk_detection_results_unit" CHECK (check_type in ('inactive', 'leaver') or org_unit_id is not null),
  CONSTRAINT "chk_detection_results_flagged_qty" CHECK (flagged_qty is null or flagged_qty >= 0),
  CONSTRAINT "chk_detection_results_since" CHECK ((coalesce(flagged_qty, 0) > 0) = (flagged_since is not null))
);

CREATE TABLE "audit_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "actor_id" bigint,
  "action" varchar(50) NOT NULL,
  "entity_type" varchar(60) NOT NULL,
  "entity_id" bigint NOT NULL,
  "old_values" jsonb,
  "new_values" jsonb,
  "reason" text,
  "correlation_id" varchar(64),
  "ip_address" varchar(45),
  "occurred_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "data_overrides" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "org_unit_id" bigint NOT NULL,
  "field_name" varchar(60) NOT NULL,
  "original_value" text,
  "override_value" text NOT NULL,
  "reason" text NOT NULL,
  "overridden_by" bigint NOT NULL,
  "overridden_at" timestamptz NOT NULL DEFAULT (now()),
  "reverted_at" timestamptz
);

